/* G2 (Normal Academic) Sec 2 generators, part C: Ch10 Volume and Surface Area of Pyramids, Cones and Spheres,
   Ch11 Statistical Diagrams, Ch12 Measures of Central Tendency, Ch13 Probability.
   Sec 2 banks are 10 multiple choice + 10 typed (each bank has 5 word problems). Style follows the Shing Lee N(A) practice
   exercises and the G2 chapter worksheets in the Shinglee folder (SLWS). Every answer is computed from the question's own numbers.
   Solids use pi = 22/7 with sizes chosen so every answer is exact. Diagrams are described by their data. */
'use strict';
module.exports = function(H){
  const {N, mcq, gcd, sp} = H;
  const U = s => v => H.numText(v) + ' ' + s;
  const cm = U('cm'), cm2 = U('cm²'), cm3 = U('cm³'), m2 = U('m²'), m3 = U('m³');
  const dol = v => '\\$' + (Number.isInteger(+v) ? sp(+v) : (+v).toFixed(2));
  const list = a => a.join(', ');
  const sumTo = (r, n, lo, hi) => { for (let t = 0; t < 300; t++){ const a = []; for (let i = 0; i < n - 1; i++) a.push(r.int(lo, hi)); const s = a.reduce((x, y) => x + y, 0); for (let last = lo; last <= hi; last++) if ((s + last) % n === 0){ a.push(last); return r.shuffle(a); } } return null; };
  const median = a => { const b = a.slice().sort((x, y) => x - y), n = b.length; return n % 2 ? b[(n - 1) / 2] : (b[n / 2 - 1] + b[n / 2]) / 2; };
  const gyms = [];
  const PYR = [[3, 4, 5], [6, 8, 10], [5, 12, 13], [9, 12, 15]];        // half-base, height, slant height of a square pyramid
  const CONE = [[7, 24, 25], [21, 28, 35], [21, 20, 29], [14, 48, 50]]; // radius, height, slant height of a cone

  /* ---- Pyramids ---- */
  gyms.push({id: 'G2.2.volume-and-surface-area-of-pyramids-cones-and-spheres.1', plain: [
    r => { const b = r.int(2, 8) * 3, h = r.int(3, 12); return N(`A square-based pyramid has a base of side ${b} cm and a height of ${h} cm. Find its volume, in cm³.`, b * b * h / 3, `Volume = ⅓ × base area × height = ⅓ × ${b * b} × ${h} = ${b * b * h / 3} cm³.`, {wr: [b * b * h, b * h / 3, b * b * h / 6, b * b * h / 3 + b], f: cm3}); },
    r => { const l = r.int(4, 12), w = r.int(3, 9) * 3 / 3 * (r.int(1, 3)), h = r.int(3, 9) * 3; return N(`A pyramid has a rectangular base ${l} cm by ${w} cm and a height of ${h} cm. Find its volume, in cm³.`, l * w * h / 3, `Volume = ⅓ × ${l} × ${w} × ${h} = ${l * w * h / 3} cm³.`, {wr: [l * w * h, l * w * h / 2, l * w * h / 3 + l, (l + w) * h / 3], f: cm3}); },
    r => { const t = r.pick(PYR), k = r.int(1, 3), a = t[0] * k, h = t[1] * k, s = t[2] * k; return N(`A square-based pyramid has a base of side ${2 * a} cm and a vertical height of ${h} cm. Find the slant height of a triangular face, in cm.`, s, `Slant height² = ${a}² + ${h}² = ${s * s}, so the slant height is ${s} cm.`, {wr: [a + h, s * s, h - a, s + 1], f: cm}); },
    r => { const t = r.pick(PYR), a = t[0], h = t[1], s = t[2]; return N(`A square-based pyramid has a base of side ${2 * a} cm and a slant height of ${s} cm. Find the area of one triangular face, in cm².`, a * s, `Area of one face = ½ × ${2 * a} × ${s} = ${a * s} cm².`, {wr: [2 * a * s, a * h, a * s / 2, a * s + a], f: cm2}); },
    r => { const t = r.pick(PYR), a = t[0], s = t[2]; return N(`A square-based pyramid has a base of side ${2 * a} cm and a slant height of ${s} cm. Find its total surface area, in cm².`, 4 * a * a + 4 * a * s, `Base = ${4 * a * a}. Four triangular faces = 4 × ½ × ${2 * a} × ${s} = ${4 * a * s}. Total = ${4 * a * a + 4 * a * s} cm².`, {wr: [4 * a * s, 4 * a * a, 4 * a * a + 2 * a * s, 4 * a * a + 4 * a * s + a], f: cm2}); },
    r => { const b = r.int(2, 8) * 3, h = r.int(3, 12), V = b * b * h / 3; return N(`A square-based pyramid has a base of side ${b} cm and a volume of ${sp(V)} cm³. Find its height, in cm.`, h, `Height = 3 × volume ÷ base area = 3 × ${V} ÷ ${b * b} = ${h} cm.`, {wr: [V / (b * b), 3 * V / b, h + 1, h * 3], f: cm}); },
    r => { const b = r.int(4, 12), h = r.int(4, 12); return N(`A pyramid and a prism have the same square base of side ${b * 3} cm and the same height ${h} cm. The volume of the prism is ${9 * b * b * h} cm³. Find the volume of the pyramid, in cm³.`, 3 * b * b * h, `The pyramid has ⅓ of the volume of the prism: ${9 * b * b * h} ÷ 3 = ${3 * b * b * h} cm³.`, {wr: [9 * b * b * h / 2, 9 * b * b * h, 3 * b * b * h + b, 27 * b * b * h], f: cm3}); },
    r => { const a = r.int(2, 6) * 3, h = r.int(2, 9); return N(`A pyramid has a triangular base with area ${a * 2} cm² and a height of ${h * 3} cm. Find its volume, in cm³.`, a * 2 * h, `Volume = ⅓ × ${a * 2} × ${h * 3} = ${a * 2 * h} cm³.`, {wr: [a * 2 * h * 3, a * 2 * h / 2, a * 2 + h * 3, a * 2 * h + a], f: cm3}); },
    r => mcq(r, 'Which of the following gives the volume of a pyramid?', '$\\dfrac{1}{3} \\times \\text{base area} \\times \\text{height}$', ['$\\text{base area} \\times \\text{height}$', '$\\dfrac{1}{2} \\times \\text{base area} \\times \\text{height}$', '$\\dfrac{1}{3} \\times \\text{base perimeter} \\times \\text{height}$'], 'The volume of a pyramid is one third of the volume of the prism with the same base and height.'),
    r => mcq(r, 'How many faces does a square-based pyramid have?', '5', ['4', '6', '8'], 'A square-based pyramid has 1 square base and 4 triangular faces, so 5 faces.')
  ], word: [
    r => { const b = r.int(3, 10) * 3, h = r.int(4, 12); return N(`A tent is a square-based pyramid with a base of side ${b} m and a height of ${h} m. Find the volume of air inside, in m³.`, b * b * h / 3, `Volume = ⅓ × ${b * b} × ${h} = ${b * b * h / 3} m³.`, {wr: [b * b * h, b * b * h / 3 + b, b * h / 3, b * b * h / 6], f: m3}); },
    r => { const t = r.pick(PYR), a = t[0], s = t[2]; return N(`A square-based pyramid roof has a base of side ${2 * a} m and a slant height of ${s} m. Find the area of the four triangular faces of the roof, in m².`, 4 * a * s, `Each face = ½ × ${2 * a} × ${s} = ${a * s} m². Four faces = ${4 * a * s} m².`, {wr: [a * s, 2 * a * s, 4 * a * s + 4 * a * a, 4 * a * a], f: m2}); },
    r => { const b = r.int(2, 6) * 3, h = r.int(3, 9), c = r.int(2, 5); return N(`A solid sandstone pyramid has a square base of side ${b} m and a height of ${h} m. Sandstone costs \\$${c} per m³. Find the cost of the sandstone, in dollars.`, b * b * h / 3 * c, `Volume = ⅓ × ${b * b} × ${h} = ${b * b * h / 3} m³. Cost = ${b * b * h / 3} × ${c} = ${b * b * h / 3 * c} dollars.`, {wr: [b * b * h * c, b * b * h / 3, b * b * h / 3 + c], f: dol}); },
    r => { const t = r.pick(PYR), a = t[0], h = t[1]; return N(`A pyramid-shaped paperweight has a square base of side ${2 * a} cm. Its volume is ${4 * a * a * h / 3} cm³. Find its height, in cm.`, h, `Height = 3 × ${4 * a * a * h / 3} ÷ ${4 * a * a} = ${h} cm.`, {wr: [h + a, 3 * h, h - 1, 2 * h], f: cm}); },
    r => { const a = r.int(2, 5) * 3, k = r.int(2, 4); return N(`A glass pyramid has a square base of side ${a} cm and a height of ${a} cm. A second pyramid has the same base and ${k} times the height. Find the volume of the second pyramid, in cm³.`, a * a * a * k / 3, `Volume = ⅓ × ${a * a} × ${a * k} = ${a * a * a * k / 3} cm³.`, {wr: [a * a * a / 3, a * a * a * k, a * a * a * k / 3 + a], f: cm3}); }
  ]});

  /* ---- Cones ---- */
  gyms.push({id: 'G2.2.volume-and-surface-area-of-pyramids-cones-and-spheres.2', plain: [
    r => { const t = r.pick(CONE), k = t[0], h = t[1]; return N(`A cone has a base radius of ${k} cm and a vertical height of ${h} cm. Find its volume, in cm³. Take π = 22/7.`, 22 / 7 * k * k * h / 3, `Volume = ⅓πr²h = ⅓ × 22/7 × ${k}² × ${h} = ${22 / 7 * k * k * h / 3} cm³.`, {wr: [22 / 7 * k * k * h, 22 / 7 * k * h / 3, 22 / 7 * k * k * h / 6, 22 / 7 * k * k * h / 3 + k], f: cm3}); },
    r => { const t = r.pick(CONE), k = t[0], l = t[2]; return N(`A cone has a base radius of ${k} cm and a slant height of ${l} cm. Find its curved surface area, in cm². Take π = 22/7.`, 22 / 7 * k * l, `Curved surface area = πrl = 22/7 × ${k} × ${l} = ${22 / 7 * k * l} cm².`, {wr: [2 * 22 / 7 * k * l, 22 / 7 * k * k, 22 / 7 * k * l / 3, 22 / 7 * k * l + k], f: cm2}); },
    r => { const t = r.pick(CONE), k = t[0], h = t[1], l = t[2]; return N(`A cone has a base radius of ${k} cm and a vertical height of ${h} cm. Find its slant height, in cm.`, l, `Slant height² = ${k}² + ${h}² = ${l * l}, so the slant height is ${l} cm.`, {wr: [k + h, l * l, h - k, l + 1], f: cm}); },
    r => { const t = r.pick(CONE), k = t[0], l = t[2]; return N(`A cone has a base radius of ${k} cm and a slant height of ${l} cm. Find its total surface area, in cm². Take π = 22/7.`, 22 / 7 * k * (k + l), `Total surface area = πr(r + l) = 22/7 × ${k} × ${k + l} = ${22 / 7 * k * (k + l)} cm².`, {wr: [22 / 7 * k * l, 22 / 7 * k * k, 2 * 22 / 7 * k * (k + l), 22 / 7 * k * (k + l) + k], f: cm2}); },
    r => { const t = r.pick(CONE), k = t[0], h = t[1], V = 22 / 7 * k * k * h / 3; return N(`A cone has a base radius of ${k} cm and a volume of ${sp(V)} cm³. Find its height, in cm. Take π = 22/7.`, h, `Height = 3V ÷ (πr²) = 3 × ${V} ÷ (22/7 × ${k}²) = ${h} cm.`, {wr: [h * 3, h / 3, h + 1, V / k], f: cm}); },
    r => { const k = r.pick([7, 14, 21]), h = r.int(1, 4) * 3; return N(`A cone and a cylinder have the same base radius ${k} cm and the same height ${h} cm. The cylinder has a volume of ${22 / 7 * k * k * h} cm³. Find the volume of the cone, in cm³. Take π = 22/7.`, 22 / 7 * k * k * h / 3, `The cone is one third of the cylinder: ${22 / 7 * k * k * h} ÷ 3 = ${22 / 7 * k * k * h / 3} cm³.`, {wr: [22 / 7 * k * k * h / 2, 22 / 7 * k * k * h * 3, 22 / 7 * k * k * h / 3 + k], f: cm3}); },
    r => { const k = r.pick([7, 14, 21]), h = r.int(1, 5) * 3; return N(`The area of the circular base of a cone is ${22 / 7 * k * k} cm² and its height is ${h} cm. Find its volume, in cm³.`, 22 / 7 * k * k * h / 3, `Volume = ⅓ × base area × height = ⅓ × ${22 / 7 * k * k} × ${h} = ${22 / 7 * k * k * h / 3} cm³.`, {wr: [22 / 7 * k * k * h, 22 / 7 * k * k * h / 2, 22 / 7 * k * k * h / 3 + h], f: cm3}); },
    r => { const t = r.pick(CONE), k = t[0], l = t[2]; return N(`A cone has a diameter of ${2 * k} cm and a slant height of ${l} cm. Find its curved surface area, in cm². Take π = 22/7.`, 22 / 7 * k * l, `The radius is ${k} cm. Curved surface area = πrl = 22/7 × ${k} × ${l} = ${22 / 7 * k * l} cm².`, {wr: [22 / 7 * 2 * k * l, 22 / 7 * k * k, 22 / 7 * k * l + l], f: cm2}); },
    r => mcq(r, 'Which of the following gives the volume of a cone with radius $r$ and height $h$?', '$\\dfrac{1}{3}\\pi r^2 h$', ['$\\pi r^2 h$', '$\\dfrac{1}{3}\\pi r h$', '$\\dfrac{1}{2}\\pi r^2 h$'], 'The volume of a cone is one third of the volume of the cylinder with the same base and height.'),
    r => mcq(r, 'Which of the following gives the curved surface area of a cone with radius $r$ and slant height $l$?', '$\\pi r l$', ['$\\pi r^2$', '$2\\pi r l$', '$\\dfrac{1}{3}\\pi r^2 l$'], 'The curved surface area of a cone is πrl, where l is the slant height.')
  ], word: [
    r => { const t = r.pick(CONE), k = t[0], h = t[1]; return N(`An ice-cream cone has a base radius of ${k} cm and a height of ${h} cm. How much ice cream fits exactly in the cone, in cm³? Take π = 22/7.`, 22 / 7 * k * k * h / 3, `Volume = ⅓ × 22/7 × ${k}² × ${h} = ${22 / 7 * k * k * h / 3} cm³.`, {wr: [22 / 7 * k * k * h, 22 / 7 * k * h / 3, 22 / 7 * k * k * h / 6], f: cm3}); },
    r => { const t = r.pick(CONE), k = t[0], l = t[2]; return N(`A party hat is a cone of radius ${k} cm and slant height ${l} cm. Find the area of paper needed to make the curved surface of the hat, in cm². Take π = 22/7.`, 22 / 7 * k * l, `Curved surface area = 22/7 × ${k} × ${l} = ${22 / 7 * k * l} cm².`, {wr: [2 * 22 / 7 * k * l, 22 / 7 * k * k, 22 / 7 * k * l + k], f: cm2}); },
    r => { const t = r.pick(CONE), k = t[0], h = t[1], c = r.int(2, 4); return N(`A cone-shaped funnel has a radius of ${k} cm and a height of ${h} cm. It is filled with water. Find the volume of water, in cm³. Take π = 22/7.`, 22 / 7 * k * k * h / 3, `Volume = ⅓ × 22/7 × ${k}² × ${h} = ${22 / 7 * k * k * h / 3} cm³.`, {wr: [22 / 7 * k * k * h, 22 / 7 * k * k * h / 3 + k, 22 / 7 * k * h / 3], f: cm3}); },
    r => { const t = r.pick(CONE), k = t[0], h = t[1], l = t[2]; return N(`A traffic cone has a base radius of ${k} cm and a vertical height of ${h} cm. Find its slant height, in cm.`, l, `Slant height² = ${k}² + ${h}² = ${l * l}, so it is ${l} cm.`, {wr: [k + h, l * l, h - k, l + 1], f: cm}); },
    r => { const k = r.pick([7, 14, 21]), h = r.int(1, 4) * 3; return N(`A cone-shaped pile of sand has a base radius of ${k} m and a height of ${h} m. Find the volume of the sand, in m³. Take π = 22/7.`, 22 / 7 * k * k * h / 3, `Volume = ⅓ × 22/7 × ${k}² × ${h} = ${22 / 7 * k * k * h / 3} m³.`, {wr: [22 / 7 * k * k * h, 22 / 7 * k * k * h / 2, 22 / 7 * k * h / 3], f: m3}); }
  ]});

  /* ---- Spheres and hemispheres ---- */
  gyms.push({id: 'G2.2.volume-and-surface-area-of-pyramids-cones-and-spheres.3', plain: [
    r => { const k = r.pick([21, 10.5]); return N(`Find the volume of a sphere of radius ${k} cm. Take π = 22/7. Give your answer in cm³.`, 4 / 3 * 22 / 7 * k ** 3, `Volume = 4/3 × π × r³ = 4/3 × 22/7 × ${k}³ = ${4 / 3 * 22 / 7 * k ** 3} cm³.`, {wr: [4 * 22 / 7 * k * k, 22 / 7 * k ** 3, 2 / 3 * 22 / 7 * k ** 3, 4 / 3 * 22 / 7 * k * k], f: cm3}); },
    r => { const k = r.pick([3.5, 7, 10.5, 14, 21]); return N(`Find the surface area of a sphere of radius ${k} cm. Take π = 22/7. Give your answer in cm².`, 4 * 22 / 7 * k * k, `Surface area = 4πr² = 4 × 22/7 × ${k}² = ${4 * 22 / 7 * k * k} cm².`, {wr: [22 / 7 * k * k, 2 * 22 / 7 * k * k, 4 / 3 * 22 / 7 * k ** 3, 4 * 22 / 7 * k], f: cm2}); },
    r => { const k = r.pick([21, 10.5]); return N(`Find the volume of a hemisphere of radius ${k} cm. Take π = 22/7. Give your answer in cm³.`, 2 / 3 * 22 / 7 * k ** 3, `Volume = 2/3 × π × r³ = 2/3 × 22/7 × ${k}³ = ${2 / 3 * 22 / 7 * k ** 3} cm³.`, {wr: [4 / 3 * 22 / 7 * k ** 3, 22 / 7 * k ** 3, 2 / 3 * 22 / 7 * k * k], f: cm3}); },
    r => { const k = r.pick([3.5, 7, 10.5, 14, 21]); return N(`Find the curved surface area of a hemisphere of radius ${k} cm. Take π = 22/7. Give your answer in cm².`, 2 * 22 / 7 * k * k, `Curved surface area = 2πr² = 2 × 22/7 × ${k}² = ${2 * 22 / 7 * k * k} cm².`, {wr: [4 * 22 / 7 * k * k, 3 * 22 / 7 * k * k, 22 / 7 * k * k, 2 * 22 / 7 * k], f: cm2}); },
    r => { const k = r.pick([3.5, 7, 10.5, 14]); return N(`Find the total surface area of a solid hemisphere of radius ${k} cm. Take π = 22/7. Give your answer in cm².`, 3 * 22 / 7 * k * k, `Total surface area = 3πr² = 3 × 22/7 × ${k}² = ${3 * 22 / 7 * k * k} cm².`, {wr: [2 * 22 / 7 * k * k, 4 * 22 / 7 * k * k, 22 / 7 * k * k, 3 * 22 / 7 * k], f: cm2}); },
    r => { const k = r.pick([7, 14, 21]); return N(`A sphere has a surface area of ${4 * 22 / 7 * k * k} cm². Find its radius, in cm. Take π = 22/7.`, k, `4 × 22/7 × r² = ${4 * 22 / 7 * k * k}, so r² = ${k * k} and r = ${k} cm.`, {wr: [k * k, 2 * k, k + 7, k / 2], f: cm}); },
    r => { const k = r.pick([7, 14, 21]); return N(`A sphere has a diameter of ${2 * k} cm. Find its surface area, in cm². Take π = 22/7.`, 4 * 22 / 7 * k * k, `The radius is ${k} cm. Surface area = 4 × 22/7 × ${k}² = ${4 * 22 / 7 * k * k} cm².`, {wr: [4 * 22 / 7 * 4 * k * k, 22 / 7 * k * k, 2 * 22 / 7 * k * k], f: cm2}); },
    r => { const k = r.pick([21, 10.5]), V = 4 / 3 * 22 / 7 * k ** 3; return N(`A sphere has a volume of ${sp(V)} cm³. Find its radius, in cm. Take π = 22/7.`, k, `4/3 × 22/7 × r³ = ${V}, so r³ = ${k ** 3} and r = ${k} cm.`, {wr: [k * 2, k ** 3, k / 2, k + 7], f: cm}); },
    r => mcq(r, 'Which of the following gives the volume of a sphere with radius $r$?', '$\\dfrac{4}{3}\\pi r^3$', ['$4\\pi r^2$', '$\\dfrac{2}{3}\\pi r^3$', '$\\pi r^3$'], 'The volume of a sphere is 4/3 π r³. The surface area is 4πr².'),
    r => mcq(r, 'A hemisphere is half of a sphere. Which of the following gives its total surface area (curved surface and flat circular face)?', '$3\\pi r^2$', ['$2\\pi r^2$', '$4\\pi r^2$', '$\\pi r^2$'], 'The curved surface is 2πr² and the flat circular face is πr², so the total is 3πr².')
  ], word: [
    r => { const k = r.pick([7, 14, 21]); return N(`A ball has a radius of ${k} cm. Find the area of leather needed to cover its surface, in cm². Take π = 22/7.`, 4 * 22 / 7 * k * k, `Surface area = 4 × 22/7 × ${k}² = ${4 * 22 / 7 * k * k} cm².`, {wr: [22 / 7 * k * k, 2 * 22 / 7 * k * k, 4 / 3 * 22 / 7 * k ** 3], f: cm2}); },
    r => { const k = r.pick([21, 10.5]); return N(`A spherical water tank has a radius of ${k} cm. Find the volume of water it holds when full, in cm³. Take π = 22/7.`, 4 / 3 * 22 / 7 * k ** 3, `Volume = 4/3 × 22/7 × ${k}³ = ${4 / 3 * 22 / 7 * k ** 3} cm³.`, {wr: [4 * 22 / 7 * k * k, 2 / 3 * 22 / 7 * k ** 3, 22 / 7 * k ** 3], f: cm3}); },
    r => { const k = r.pick([7, 14, 21]); return N(`A bowl is a hollow hemisphere with a radius of ${k} cm. Find the area of its curved inner surface, in cm². Take π = 22/7.`, 2 * 22 / 7 * k * k, `Curved surface area = 2 × 22/7 × ${k}² = ${2 * 22 / 7 * k * k} cm².`, {wr: [4 * 22 / 7 * k * k, 3 * 22 / 7 * k * k, 22 / 7 * k * k], f: cm2}); },
    r => { const k = r.pick([21, 10.5]); return N(`A dome is a solid hemisphere of radius ${k} m. Find its volume, in m³. Take π = 22/7.`, 2 / 3 * 22 / 7 * k ** 3, `Volume = 2/3 × 22/7 × ${k}³ = ${2 / 3 * 22 / 7 * k ** 3} m³.`, {wr: [4 / 3 * 22 / 7 * k ** 3, 22 / 7 * k ** 3, 2 / 3 * 22 / 7 * k * k], f: m3}); },
    r => { const k = r.pick([7, 14]); return N(`A solid metal hemisphere has a radius of ${k} cm. Find its total surface area, including the flat face, in cm². Take π = 22/7.`, 3 * 22 / 7 * k * k, `Total surface area = 3 × 22/7 × ${k}² = ${3 * 22 / 7 * k * k} cm².`, {wr: [2 * 22 / 7 * k * k, 4 * 22 / 7 * k * k, 22 / 7 * k * k], f: cm2}); }
  ]});

  /* ---- Dot diagrams ---- */
  const dots = r => { const lo = r.int(1, 4), vals = [lo, lo + 1, lo + 2, lo + 3, lo + 4], f = vals.map(() => r.int(1, 6)); return {vals, f}; };
  const dotText = d => d.vals.map((v, i) => `${d.f[i]} dot${d.f[i] === 1 ? '' : 's'} at ${v}`).join(', ');
  gyms.push({id: 'G2.2.statistical-diagrams.1', plain: [
    r => { const d = dots(r), T = d.f.reduce((a, b) => a + b, 0); return N(`A dot diagram shows the number of goals scored by a team: ${dotText(d)}. How many matches does the diagram show?`, T, `Add the numbers of dots: ${d.f.join(' + ')} = ${T}.`, {wr: [T + 1, T - 1, d.vals.length, Math.max(...d.f)]}); },
    r => { const d = dots(r), m = Math.max(...d.f); if (d.f.filter(x => x === m).length > 1) return null; const mode = d.vals[d.f.indexOf(m)]; return N(`A dot diagram shows: ${dotText(d)}. Find the mode of the data.`, mode, `The value with the most dots is ${mode} (${m} dots), so the mode is ${mode}.`, {wr: [m, d.vals[0], d.vals[4], mode + 1]}); },
    r => { const d = dots(r), x = d.vals[2]; const c = d.vals.reduce((t, v, i) => v > x ? t + d.f[i] : t, 0); return N(`A dot diagram shows: ${dotText(d)}. How many values are greater than ${x}?`, c, `Add the dots above ${x}: ${d.vals.map((v, i) => v > x ? d.f[i] : null).filter(v => v !== null).join(' + ')} = ${c}.`, {wr: [c + d.f[2], c + 1, c - 1, d.f.reduce((a, b) => a + b, 0)]}); },
    r => { const d = dots(r); return N(`A dot diagram shows: ${dotText(d)}. Find the range of the data.`, d.vals[4] - d.vals[0], `Range = largest − smallest = ${d.vals[4]} − ${d.vals[0]} = ${d.vals[4] - d.vals[0]}.`, {wr: [d.vals[4], d.vals[0], d.vals[4] - d.vals[0] + 1, 5]}); },
    r => { const d = dots(r), T = d.f.reduce((a, b) => a + b, 0), S = d.vals.reduce((t, v, i) => t + v * d.f[i], 0); return N(`A dot diagram shows: ${dotText(d)}. Find the total of all the values.`, S, `Multiply each value by its number of dots and add: ${d.vals.map((v, i) => v + '×' + d.f[i]).join(' + ')} = ${S}.`, {wr: [T, S + T, S - d.vals[0], d.vals.reduce((a, b) => a + b, 0)]}); },
    r => { const d = dots(r), x = d.vals[1], c = d.f[1] + d.f[0]; return N(`A dot diagram shows: ${dotText(d)}. How many values are ${x} or less?`, c, `Add the dots at ${d.vals[0]} and ${x}: ${d.f[0]} + ${d.f[1]} = ${c}.`, {wr: [d.f[1], c + 1, c + d.f[2], d.f[0]]}); },
    r => { const d = dots(r), i = r.int(0, 4); return N(`A dot diagram shows: ${dotText(d)}. How many dots are at the value ${d.vals[i]}?`, d.f[i], `Read the dots at ${d.vals[i]}: ${d.f[i]}.`, {wr: [d.f[i] + 1, d.f[i] - 1 < 0 ? d.f[i] + 2 : d.f[i] - 1, d.vals[i], d.f.reduce((a, b) => a + b, 0)]}); },
    r => mcq(r, 'A dot diagram is best used to show which kind of data?', 'a small set of whole-number data', ['continuous data grouped into classes', 'parts of a whole', 'changes over a long time'], 'A dot diagram shows each value as a dot above a number line, so it suits a small amount of discrete data.'),
    r => mcq(r, 'In a dot diagram, what does the number of dots above a value represent?', 'the frequency of that value', ['the value itself', 'the mean of the data', 'the range of the data'], 'Each dot stands for one observation, so the dots above a value show its frequency.')
  ], word: [
    r => { const d = dots(r), T = d.f.reduce((a, b) => a + b, 0); return N(`A dot diagram shows the number of books ${T} students read in a month: ${dotText(d)}. How many students are in the group?`, T, `${d.f.join(' + ')} = ${T} students.`, {wr: [T + 1, T - 1, d.vals.length, d.f[0] + d.f[1]]}); },
    r => { const d = dots(r), T = d.f.reduce((a, b) => a + b, 0), x = d.vals[3], c = d.f[3] + d.f[4]; return N(`A dot diagram shows the number of siblings of students in a class: ${dotText(d)}. How many students have ${x} or more siblings?`, c, `${d.f[3]} + ${d.f[4]} = ${c}.`, {wr: [d.f[3], c + 1, T - c, c - 1]}); },
    r => { const d = dots(r), m = Math.max(...d.f); if (d.f.filter(x => x === m).length > 1) return null; const mode = d.vals[d.f.indexOf(m)]; return N(`A shop recorded the number of customers buying a drink: ${dotText(d)} (values are the numbers of drinks bought). What is the most common number of drinks bought?`, mode, `The most dots are at ${mode}, so the mode is ${mode}.`, {wr: [m, d.vals[0], mode + 1, d.vals[4]]}); },
    r => { const d = dots(r), S = d.vals.reduce((t, v, i) => t + v * d.f[i], 0); return N(`A dot diagram shows the number of goals scored in each match: ${dotText(d)}. How many goals were scored in total?`, S, `${d.vals.map((v, i) => v + '×' + d.f[i]).join(' + ')} = ${S}.`, {wr: [d.f.reduce((a, b) => a + b, 0), S + 5, S - d.vals[0], d.vals.reduce((a, b) => a + b, 0)]}); },
    r => { const d = dots(r), T = d.f.reduce((a, b) => a + b, 0); return N(`A dot diagram shows how many pets each of ${T} students has: ${dotText(d)}. Find the range of the number of pets.`, d.vals[4] - d.vals[0], `${d.vals[4]} − ${d.vals[0]} = ${d.vals[4] - d.vals[0]}.`, {wr: [d.vals[4], d.vals[0], T, 5]}); }
  ]});

  /* ---- Histograms ---- */
  const hist = r => { const w = r.pick([5, 10]), lo = r.pick([0, 10, 20]), f = [r.int(2, 9), r.int(4, 14), r.int(6, 16), r.int(3, 12), r.int(1, 8)]; return {w, lo, f, cls: f.map((_, i) => `${lo + i * w} – ${lo + (i + 1) * w}`)}; };
  const histText = h => h.cls.map((c, i) => `${c} (${h.f[i]})`).join(', ');
  gyms.push({id: 'G2.2.statistical-diagrams.2', plain: [
    r => { const h = hist(r), T = h.f.reduce((a, b) => a + b, 0); return N(`A histogram shows the marks of students in classes (frequency in brackets): ${histText(h)}. How many students are there in total?`, T, `${h.f.join(' + ')} = ${T}.`, {wr: [T + 1, T - 2, Math.max(...h.f), h.f.length]}); },
    r => { const h = hist(r); return N(`A histogram has classes ${h.cls.join(', ')}. What is the class width?`, h.w, `Each class covers ${h.w} marks, e.g. ${h.lo + h.w} − ${h.lo} = ${h.w}.`, {wr: [h.w * 2, h.w + 5, h.w / 2, h.lo + h.w]}); },
    r => { const h = hist(r), m = Math.max(...h.f); if (h.f.filter(x => x === m).length > 1) return null; return N(`A histogram shows (frequency in brackets): ${histText(h)}. What is the highest frequency?`, m, `The tallest bar has frequency ${m}.`, {wr: [m + 1, m - 1, Math.min(...h.f), h.f.reduce((a, b) => a + b, 0)]}); },
    r => { const h = hist(r), x = r.int(2, 4); const c = h.f.slice(x).reduce((a, b) => a + b, 0); return N(`A histogram shows (frequency in brackets): ${histText(h)}. How many students scored ${h.lo + x * h.w} or more?`, c, `Add the frequencies of the classes from ${h.cls[x]} upwards: ${h.f.slice(x).join(' + ')} = ${c}.`, {wr: [c + h.f[x - 1], c - 1, h.f[x], c + 1]}); },
    r => { const h = hist(r), c = h.f[0] + h.f[1]; return N(`A histogram shows (frequency in brackets): ${histText(h)}. How many students scored less than ${h.lo + 2 * h.w}?`, c, `Add the first two classes: ${h.f[0]} + ${h.f[1]} = ${c}.`, {wr: [h.f[1], c + h.f[2], c + 1, h.f[0]]}); },
    r => { const k = r.pick([2, 4, 5, 10]), T = k * r.int(3, 8), a = T / k * r.int(1, k - 1 || 1); return N(`In a histogram of ${T} students, the bar for the class 40 – 50 has frequency ${a}. What percentage of the students are in that class?`, a * 100 / T, `${a} ÷ ${T} × 100% = ${a * 100 / T}%.`, {wr: [a, a * 100 / T + 10, 100 - a * 100 / T, T], f: v => v + '%'}); },
    r => { const h = hist(r), T = h.f.reduce((a, b) => a + b, 0), i = r.int(0, 4); return N(`A histogram shows (frequency in brackets): ${histText(h)}. How many students are in the class ${h.cls[i]}?`, h.f[i], `Read the frequency of the class ${h.cls[i]}: ${h.f[i]}.`, {wr: [h.f[i] + 1, h.f[i] - 1 < 0 ? h.f[i] + 2 : h.f[i] - 1, T, h.f[(i + 1) % 5]]}); },
    r => { const h = hist(r), T = h.f.reduce((a, b) => a + b, 0), a = h.f[1] + h.f[2]; return N(`A histogram shows (frequency in brackets): ${histText(h)}. How many students scored from ${h.lo + h.w} to less than ${h.lo + 3 * h.w}?`, a, `Add the classes ${h.cls[1]} and ${h.cls[2]}: ${h.f[1]} + ${h.f[2]} = ${a}.`, {wr: [h.f[1], a + h.f[3], T - a, a + 1]}); },
    r => { const h = hist(r), m = Math.max(...h.f); if (h.f.filter(x => x === m).length > 1) return null; return mcq(r, `A histogram shows (frequency in brackets): ${histText(h)}. Which is the modal class?`, h.cls[h.f.indexOf(m)], h.cls.filter((_, i) => i !== h.f.indexOf(m)).slice(0, 3), `The modal class is the class with the highest frequency, ${m}.`); },
    r => mcq(r, 'What is the main difference between a bar chart and a histogram?', 'A histogram shows continuous data in classes with no gaps between bars', ['A histogram has gaps between the bars', 'A bar chart shows continuous data', 'There is no difference'], 'A histogram is used for grouped continuous data, so the bars touch.')
  ], word: [
    r => { const h = hist(r), T = h.f.reduce((a, b) => a + b, 0); return N(`A teacher draws a histogram of ${T} students' test marks in classes (frequency in brackets): ${histText(h)}. How many students took the test?`, T, `${h.f.join(' + ')} = ${T}.`, {wr: [T + 1, T - 1, Math.max(...h.f), h.f.length * 5]}); },
    r => { const h = hist(r), c = h.f[3] + h.f[4]; return N(`A histogram shows the time ${h.f.reduce((a, b) => a + b, 0)} runners took (in minutes, frequency in brackets): ${histText(h)}. How many runners took ${h.lo + 3 * h.w} minutes or more?`, c, `${h.f[3]} + ${h.f[4]} = ${c}.`, {wr: [h.f[3], c + 1, c + h.f[2], h.f[4]]}); },
    r => { const h = hist(r), T = h.f.reduce((a, b) => a + b, 0), p = h.f[2]; return N(`A histogram shows the heights of ${T} plants (frequency in brackets): ${histText(h)}. How many plants are in the class ${h.cls[2]}?`, p, `Read the frequency for ${h.cls[2]}: ${p}.`, {wr: [p + 1, p - 1, T, h.f[1]]}); },
    r => { const h = hist(r), c = h.f[0] + h.f[1] + h.f[2]; return N(`A histogram shows the ages of members of a club (frequency in brackets): ${histText(h)}. How many members are younger than ${h.lo + 3 * h.w}?`, c, `${h.f[0]} + ${h.f[1]} + ${h.f[2]} = ${c}.`, {wr: [c + h.f[3], c - h.f[0], c + 1, h.f[2]]}); },
    r => { const h = hist(r), T = h.f.reduce((a, b) => a + b, 0), a = h.f[1] + h.f[2]; return N(`A histogram shows the daily wages of ${T} workers (frequency in brackets): ${histText(h)}. How many workers earn from ${h.lo + h.w} up to less than ${h.lo + 3 * h.w} dollars?`, a, `${h.f[1]} + ${h.f[2]} = ${a}.`, {wr: [h.f[1], a + 1, T - a, h.f[2]]}); }
  ]});

  /* ---- Stem-and-leaf diagrams ---- */
  const stem = r => { const st = r.int(1, 4), stems = [st, st + 1, st + 2], n = [r.int(2, 4), r.int(3, 5), r.int(2, 4)], leaves = stems.map((s, i) => { const set = new Set(); while (set.size < n[i]) set.add(r.int(0, 9)); return [...set].sort((a, b) => a - b); }); const vals = []; stems.forEach((s, i) => leaves[i].forEach(l => vals.push(s * 10 + l))); return {stems, leaves, vals}; };
  const stemText = d => d.stems.map((s, i) => `stem ${s}: leaves ${d.leaves[i].join(' ')}`).join('; ');
  gyms.push({id: 'G2.2.statistical-diagrams.3', plain: [
    r => { const d = stem(r); return N(`A stem-and-leaf diagram has (key: 2 | 3 means 23) ${stemText(d)}. How many values are there?`, d.vals.length, `Count all the leaves: ${d.leaves.map(l => l.length).join(' + ')} = ${d.vals.length}.`, {wr: [d.vals.length + 1, d.vals.length - 1, d.stems.length, Math.max(...d.leaves.map(l => l.length))]}); },
    r => { const d = stem(r); return N(`A stem-and-leaf diagram has (key: 2 | 3 means 23) ${stemText(d)}. What is the largest value?`, Math.max(...d.vals), `The largest stem is ${d.stems[2]} with largest leaf ${Math.max(...d.leaves[2])}, so the largest value is ${Math.max(...d.vals)}.`, {wr: [Math.min(...d.vals), Math.max(...d.vals) + 1, d.stems[2], Math.max(...d.vals) - 10]}); },
    r => { const d = stem(r); return N(`A stem-and-leaf diagram has (key: 2 | 3 means 23) ${stemText(d)}. Find the range of the data.`, Math.max(...d.vals) - Math.min(...d.vals), `Range = ${Math.max(...d.vals)} − ${Math.min(...d.vals)} = ${Math.max(...d.vals) - Math.min(...d.vals)}.`, {wr: [Math.max(...d.vals), Math.min(...d.vals), Math.max(...d.vals) - Math.min(...d.vals) + 1, Math.max(...d.vals) - Math.min(...d.vals) - 1]}); },
    r => { const d = stem(r); return N(`A stem-and-leaf diagram has (key: 2 | 3 means 23) ${stemText(d)}. Find the median of the data.`, median(d.vals), `Arrange the ${d.vals.length} values in order: ${d.vals.join(', ')}. The median is ${median(d.vals)}.`, {wr: [Math.max(...d.vals), Math.min(...d.vals), median(d.vals) + 1, median(d.vals) - 1]}); },
    r => { const d = stem(r), x = d.stems[1] * 10 + 5; const c = d.vals.filter(v => v > x).length; return N(`A stem-and-leaf diagram has (key: 2 | 3 means 23) ${stemText(d)}. How many values are greater than ${x}?`, c, `The values greater than ${x} are ${d.vals.filter(v => v > x).join(', ')}, which is ${c} values.`, {wr: [c + 1, c - 1, d.vals.length - c, d.leaves[2].length]}); },
    r => { const d = stem(r), s = d.stems[1]; return N(`A stem-and-leaf diagram has (key: 2 | 3 means 23) ${stemText(d)}. How many values are in the ${s}0s (values from ${s}0 to ${s}9)?`, d.leaves[1].length, `Count the leaves on stem ${s}: ${d.leaves[1].length}.`, {wr: [d.leaves[1].length + 1, d.leaves[1].length - 1, d.leaves[0].length, d.vals.length]}); },
    r => { const d = stem(r), S = d.vals.reduce((a, b) => a + b, 0); return N(`A stem-and-leaf diagram has (key: 2 | 3 means 23) ${stemText(d)}. Find the sum of the smallest and largest values.`, Math.min(...d.vals) + Math.max(...d.vals), `${Math.min(...d.vals)} + ${Math.max(...d.vals)} = ${Math.min(...d.vals) + Math.max(...d.vals)}.`, {wr: [Math.max(...d.vals) - Math.min(...d.vals), S, Math.min(...d.vals) + Math.max(...d.vals) + 1, Math.max(...d.vals)]}); },
    r => { const v = r.int(12, 47); return mcq(r, `In a stem-and-leaf diagram with the key "2 | 3 means 23", which entry represents the value ${v}?`, `${Math.floor(v / 10)} | ${v % 10}`, [`${v % 10} | ${Math.floor(v / 10)}`, `${Math.floor(v / 10) + 1} | ${v % 10}`, `${Math.floor(v / 10)} | ${(v % 10 + 1) % 10}`], `The stem is the tens digit and the leaf is the ones digit, so ${v} is written ${Math.floor(v / 10)} | ${v % 10}.`); },
    r => mcq(r, 'Why is a stem-and-leaf diagram useful?', 'It shows the shape of the data and keeps the original values', ['It hides the original values', 'It only shows the mean', 'It only works with decimals'], 'A stem-and-leaf diagram shows the distribution while still showing every actual value.')
  ], word: [
    r => { const d = stem(r); return N(`The stem-and-leaf diagram shows the marks of a class in a quiz (key: 2 | 3 means 23): ${stemText(d)}. How many students took the quiz?`, d.vals.length, `${d.leaves.map(l => l.length).join(' + ')} = ${d.vals.length}.`, {wr: [d.vals.length + 1, d.vals.length - 1, d.stems.length, Math.max(...d.leaves.map(l => l.length))]}); },
    r => { const d = stem(r); return N(`The ages of members of a club are shown (key: 2 | 3 means 23): ${stemText(d)}. Find the age of the oldest member.`, Math.max(...d.vals), `The largest stem is ${d.stems[2]} and its largest leaf is ${Math.max(...d.leaves[2])}, so the oldest member is ${Math.max(...d.vals)}.`, {wr: [Math.min(...d.vals), Math.max(...d.vals) + 1, Math.max(...d.vals) - 10]}); },
    r => { const d = stem(r); return N(`The times, in seconds, taken by runners are shown (key: 2 | 3 means 23): ${stemText(d)}. Find the difference between the slowest and fastest times, in seconds.`, Math.max(...d.vals) - Math.min(...d.vals), `${Math.max(...d.vals)} − ${Math.min(...d.vals)} = ${Math.max(...d.vals) - Math.min(...d.vals)}.`, {wr: [Math.max(...d.vals), Math.min(...d.vals), Math.max(...d.vals) - Math.min(...d.vals) + 1]}); },
    r => { const d = stem(r); return N(`The heights, in cm, of plants are shown (key: 2 | 3 means 23): ${stemText(d)}. Find the median height, in cm.`, median(d.vals), `In order: ${d.vals.join(', ')}. The median is ${median(d.vals)}.`, {wr: [Math.max(...d.vals), Math.min(...d.vals), median(d.vals) + 1, median(d.vals) - 1]}); },
    r => { const d = stem(r), x = d.stems[1] * 10; const c = d.vals.filter(v => v >= x).length; return N(`The test marks of students are shown (key: 2 | 3 means 23): ${stemText(d)}. How many students scored ${x} or more?`, c, `Count the values of ${x} and above: ${d.vals.filter(v => v >= x).join(', ')}. That is ${c} students.`, {wr: [c + 1, c - 1, d.vals.length - c, d.leaves[1].length]}); }
  ]});

  /* ---- Mean ---- */
  gyms.push({id: 'G2.2.measures-of-central-tendency.1', plain: [
    r => { const n = r.int(4, 8), d = sumTo(r, n, 4, 30); if (!d) return null; const s = d.reduce((a, b) => a + b, 0); return N(`Find the mean of ${list(d)}.`, s / n, `Mean = ${s} ÷ ${n} = ${s / n}.`, {wr: [s, s / n + 1, s / n - 1, Math.max(...d)]}); },
    r => { const n = r.int(5, 12), m = r.int(8, 40); return N(`The mean of ${n} numbers is ${m}. Find the sum of the numbers.`, n * m, `Sum = mean × number of values = ${m} × ${n} = ${n * m}.`, {wr: [n + m, n * m - n, m, n * m + m]}); },
    r => { const n = 5, m = r.int(10, 30), a = r.int(5, m + 4), b = r.int(5, m + 4), c = r.int(5, m + 4), d = r.int(5, m + 4), x = n * m - a - b - c - d; if (x < 1) return null; return N(`The mean of five numbers is ${m}. Four of them are ${a}, ${b}, ${c} and ${d}. Find the fifth number.`, x, `Sum = 5 × ${m} = ${5 * m}. Fifth number = ${5 * m} − ${a + b + c + d} = ${x}.`, {wr: [m, a + b + c + d, x + 2, x - 2].filter(v => v > 0)}); },
    r => { const n = 5, m = r.int(10, 30), x = r.int(m + 1, m + 20); const newMean = (n * m + x) / (n + 1); if (newMean !== Math.round(newMean * 10) / 10) return null; return N(`The mean of ${n} numbers is ${m}. When another number is included, the mean of the ${n + 1} numbers is ${newMean}. Find the number that was included.`, x, `New sum = ${newMean} × ${n + 1} = ${newMean * (n + 1)}. Old sum = ${n * m}. The new number = ${newMean * (n + 1)} − ${n * m} = ${x}.`, {wr: [newMean, x + 1, x - 1, m]}); },
    r => { const v = [r.int(1, 5), r.int(1, 5), r.int(1, 5), r.int(1, 5)], f = [r.int(2, 6), r.int(2, 6), r.int(2, 6), r.int(2, 6)]; const set = new Set(v); if (set.size < 4) return null; const T = f.reduce((a, b) => a + b, 0), S = v.reduce((t, x, i) => t + x * f[i], 0); if (S % T) return null; return N(`A frequency table shows the values ${list(v)} with frequencies ${list(f)} respectively. Find the mean value.`, S / T, `Total = ${v.map((x, i) => x + '×' + f[i]).join(' + ')} = ${S}. Number of values = ${T}. Mean = ${S} ÷ ${T} = ${S / T}.`, {wr: [S, v.reduce((a, b) => a + b, 0) / 4, S / T + 1, T]}); },
    r => { const n = r.int(4, 7), d = sumTo(r, n, 10, 60); if (!d) return null; const s = d.reduce((a, b) => a + b, 0), m = s / n; return N(`The mean of ${list(d)} is ${m}. Find the mean after each number is increased by 5.`, m + 5, `Adding 5 to every value adds 5 to the mean: ${m} + 5 = ${m + 5}.`, {wr: [m, m + 5 * n, s + 5, m + 1]}); },
    r => { const n = r.int(4, 8), m = r.int(10, 40), a = r.int(2, 5); return N(`The mean of ${n} numbers is ${m}. Each number is multiplied by ${a}. Find the new mean.`, m * a, `Multiplying every value by ${a} multiplies the mean by ${a}: ${m} × ${a} = ${m * a}.`, {wr: [m + a, m * a * n, m, m * a + a]}); },
    r => { const g = r.int(3, 6), m1 = r.int(60, 80), n1 = r.int(10, 20), n2 = r.int(10, 20), m2 = r.int(60, 80); const T = n1 * m1 + n2 * m2; if (T % (n1 + n2) || m1 === m2) return null; return N(`${n1} boys have a mean mark of ${m1} and ${n2} girls have a mean mark of ${m2}. Find the mean mark of all ${n1 + n2} students.`, T / (n1 + n2), `Total = ${n1}×${m1} + ${n2}×${m2} = ${T}. Mean = ${T} ÷ ${n1 + n2} = ${T / (n1 + n2)}.`, {wr: [(m1 + m2) / 2, T, T / (n1 + n2) + 1, m1]}); },
    r => mcq(r, 'Which of the following is the formula for the mean?', 'sum of all the values ÷ number of values', ['the middle value when arranged in order', 'the most frequent value', 'largest value − smallest value'], 'The mean is the sum of all the values divided by how many values there are.'),
    r => mcq(r, 'A set of values includes an extreme high value. Which measure is most affected by it?', 'the mean', ['the median', 'the mode', 'none of them'], 'The mean uses every value, so one extreme value pulls it up; the median and mode are not.')
  ], word: [
    r => { const n = r.int(4, 7), d = sumTo(r, n, 40, 90); if (!d) return null; const s = d.reduce((a, b) => a + b, 0); return N(`A student scored ${list(d)} in ${n} tests. Find her mean score.`, s / n, `Mean = ${s} ÷ ${n} = ${s / n}.`, {wr: [s, s / n + 1, s / n - 1, Math.max(...d)]}); },
    r => { const n = r.int(5, 9), m = r.int(12, 30); return N(`The mean mass of ${n} boxes is ${m} kg. Find the total mass of the boxes, in kg.`, n * m, `Total = ${m} × ${n} = ${n * m} kg.`, {wr: [n + m, n * m + m, m, n * m - n]}); },
    r => { const m = r.int(68, 82), a = r.int(60, 90), b = r.int(60, 90), c = r.int(60, 90), x = 4 * m - a - b - c; if (x < 30 || x > 100) return null; return N(`A student's mean mark in four tests is ${m}. In three tests the marks are ${a}, ${b} and ${c}. What is the mark in the fourth test?`, x, `Total = 4 × ${m} = ${4 * m}. Fourth mark = ${4 * m} − ${a + b + c} = ${x}.`, {wr: [m, a + b + c, x + 2, x - 2]}); },
    r => { const n1 = r.pick([10, 15, 20]), n2 = r.pick([5, 10]), m1 = r.pick([60, 70, 80]), m2 = r.pick([50, 60, 70, 90]); const T = n1 * m1 + n2 * m2; if (T % (n1 + n2)) return null; return N(`In a class, ${n1} students have a mean height of ${m1 + 80} cm and ${n2} students have a mean height of ${m2 + 80} cm. Find the mean height of all ${n1 + n2} students, in cm.`, T / (n1 + n2) + 80, `Mean = (${n1}×${m1 + 80} + ${n2}×${m2 + 80}) ÷ ${n1 + n2} = ${T / (n1 + n2) + 80} cm.`, {wr: [(m1 + m2) / 2 + 80, m1 + 80, T / (n1 + n2) + 81, T / (n1 + n2) + 80 - 2]}); },
    r => { const d = sumTo(r, 5, 12, 40); if (!d) return null; const s = d.reduce((a, b) => a + b, 0); return N(`A shop sold ${list(d)} burgers on five days. Find the mean number of burgers sold per day.`, s / 5, `Mean = ${s} ÷ 5 = ${s / 5}.`, {wr: [s, s / 5 + 1, s / 5 - 1, Math.max(...d)]}); }
  ]});

  /* ---- Median ---- */
  gyms.push({id: 'G2.2.measures-of-central-tendency.2', plain: [
    r => { const n = r.pick([5, 7, 9]), d = Array.from({length: n}, () => r.int(3, 60)); return N(`Find the median of ${list(d)}.`, median(d), `Arrange in order: ${d.slice().sort((a, b) => a - b).join(', ')}. The middle value is ${median(d)}.`, {wr: [d[Math.floor(n / 2)], d.reduce((a, b) => a + b, 0) / n | 0, Math.max(...d), median(d) + 1]}); },
    r => { const n = r.pick([4, 6, 8]), d = Array.from({length: n}, () => r.int(3, 60)); return N(`Find the median of ${list(d)}.`, median(d), `Arrange in order: ${d.slice().sort((a, b) => a - b).join(', ')}. The two middle values give a median of ${median(d)}.`, {wr: [d.slice().sort((a, b) => a - b)[n / 2], d.slice().sort((a, b) => a - b)[n / 2 - 1], Math.max(...d), median(d) + 1]}); },
    r => { const n = r.pick([7, 9, 11, 13]); return N(`A set of ${n} values is arranged in order. Which position is the median? (Give the position number.)`, (n + 1) / 2, `The median is the ${(n + 1) / 2}th value because (${n} + 1) ÷ 2 = ${(n + 1) / 2}.`, {wr: [n / 2 + 1, (n - 1) / 2, n, (n + 1) / 2 + 1]}); },
    r => { const a = r.int(3, 20), b = r.int(21, 40), c = r.int(41, 60), d = r.int(61, 80), e = r.int(81, 99); return N(`The median of ${list(r.shuffle([a, b, c, d, e]))} is found. What is the median?`, c, `In order: ${a}, ${b}, ${c}, ${d}, ${e}. The middle value is ${c}.`, {wr: [b, d, (a + b + c + d + e) / 5 | 0, c + 1]}); },
    r => { const d = Array.from({length: 7}, () => r.int(10, 50)), s = d.slice().sort((a, b) => a - b); return N(`Seven values are ${list(d)}. Find the difference between the median and the smallest value.`, s[3] - s[0], `In order: ${s.join(', ')}. The median is ${s[3]}. ${s[3]} − ${s[0]} = ${s[3] - s[0]}.`, {wr: [s[3], s[6] - s[3], s[3] - s[0] + 1, s[6] - s[0]]}); },
    r => { const v = [1, 2, 3, 4, 5], f = v.map(() => r.int(1, 5)), T = f.reduce((a, b) => a + b, 0); if (T % 2 === 0) return null; let c = 0, med = 0; for (let i = 0; i < 5; i++){ c += f[i]; if (c >= (T + 1) / 2){ med = v[i]; break; } } return N(`A frequency table shows the scores 1, 2, 3, 4, 5 with frequencies ${list(f)} respectively. There are ${T} scores. Find the median score.`, med, `The median is the ${(T + 1) / 2}th value. Adding frequencies: ${f.map((_, i) => f.slice(0, i + 1).reduce((a, b) => a + b, 0)).join(', ')}. The ${(T + 1) / 2}th value is ${med}.`, {wr: [3, med + 1, med - 1 < 1 ? med + 2 : med - 1, (T + 1) / 2]}); },
    r => { const d = Array.from({length: 6}, () => r.int(5, 50)), s = d.slice().sort((a, b) => a - b); return N(`Six values are ${list(d)}. Find the median.`, (s[2] + s[3]) / 2, `In order: ${s.join(', ')}. The middle two are ${s[2]} and ${s[3]}, so the median is ${(s[2] + s[3]) / 2}.`, {wr: [s[2], s[3], s[1], (s[2] + s[3]) / 2 + 1]}); },
    r => mcq(r, 'Which of the following is the median of 3, 8, 5, 9, 11?', '8', ['5', '9', '7.2'], 'In order: 3, 5, 8, 9, 11. The middle value is 8.'),
    r => mcq(r, 'When is the median a better average than the mean?', 'When the data has a few extreme values', ['When all values are equal', 'When there are only two values', 'When the data are categories'], 'The median is not pulled by extreme values, so it describes the typical value better.')
  ], word: [
    r => { const d = Array.from({length: 7}, () => r.int(20, 90)); return N(`The marks of 7 students are ${list(d)}. Find the median mark.`, median(d), `In order: ${d.slice().sort((a, b) => a - b).join(', ')}. The median is ${median(d)}.`, {wr: [d[3], Math.max(...d), Math.min(...d), median(d) + 1]}); },
    r => { const d = Array.from({length: 8}, () => r.int(20, 90)), s = d.slice().sort((a, b) => a - b); return N(`The times, in seconds, of 8 runners are ${list(d)}. Find the median time, in seconds.`, (s[3] + s[4]) / 2, `In order: ${s.join(', ')}. The median is (${s[3]} + ${s[4]}) ÷ 2 = ${(s[3] + s[4]) / 2}.`, {wr: [s[3], s[4], Math.max(...d), (s[3] + s[4]) / 2 + 1]}); },
    r => { const d = [r.int(1500, 2500), r.int(1500, 2500), r.int(1500, 2500), r.int(1500, 2500), r.int(9000, 20000)]; const s = d.slice().sort((a, b) => a - b); return N(`Five workers earn \\$${d.join(', \\$')} a month. Find the median monthly wage, in dollars.`, s[2], `In order: ${s.join(', ')}. The middle wage is ${s[2]} dollars.`, {wr: [Math.max(...d), s[1], s[3], Math.round(d.reduce((a, b) => a + b, 0) / 5)], f: dol}); },
    r => { const d = Array.from({length: 9}, () => r.int(30, 99)); return N(`The ages of nine members of a club are ${list(d)}. Find the median age.`, median(d), `In order: ${d.slice().sort((a, b) => a - b).join(', ')}. The 5th value is the median: ${median(d)}.`, {wr: [d[4], Math.max(...d), Math.min(...d), median(d) + 1]}); },
    r => { const d = Array.from({length: 6}, () => r.int(10, 60)), s = d.slice().sort((a, b) => a - b); return N(`A shop sold ${list(d)} cups of tea over six days. Find the median number of cups sold per day.`, (s[2] + s[3]) / 2, `In order: ${s.join(', ')}. The median is (${s[2]} + ${s[3]}) ÷ 2 = ${(s[2] + s[3]) / 2}.`, {wr: [s[2], s[3], Math.max(...d), (s[2] + s[3]) / 2 + 1]}); }
  ]});

  /* ---- Mode ---- */
  const withMode = (r, n, lo, hi) => { for (let t = 0; t < 100; t++){ const d = Array.from({length: n}, () => r.int(lo, hi)), c = {}; d.forEach(v => c[v] = (c[v] || 0) + 1); const m = Math.max(...Object.values(c)); const ks = Object.keys(c).filter(k => c[k] === m); if (ks.length === 1 && m >= 2) return {d, mode: +ks[0], m}; } return null; };
  gyms.push({id: 'G2.2.measures-of-central-tendency.3', plain: [
    r => { const o = withMode(r, 11, 3, 9); if (!o) return null; return N(`Find the mode of ${list(o.d)}.`, o.mode, `${o.mode} appears ${o.m} times, more than any other value.`, {wr: [o.mode + 1, o.mode - 1, o.m, Math.max(...o.d)]}); },
    r => { const o = withMode(r, 13, 10, 16); if (!o) return null; return N(`The shoe sizes of 13 students are ${list(o.d)}. Which shoe size is the mode?`, o.mode, `${o.mode} occurs ${o.m} times, the most.`, {wr: [o.m, Math.max(...o.d), Math.min(...o.d), o.mode + 1]}); },
    r => { const v = [r.int(1, 3), r.int(4, 6), r.int(7, 9), r.int(10, 12)], f = [r.int(2, 5), r.int(2, 5), r.int(6, 9), r.int(2, 5)]; return N(`A frequency table shows the values ${list(v)} with frequencies ${list(f)} respectively. Find the mode.`, v[2], `The highest frequency is ${f[2]}, which is for the value ${v[2]}. The mode is ${v[2]}.`, {wr: [f[2], v[0], v[3], v[2] + 1]}); },
    r => { const v = [r.int(1, 3), r.int(4, 6), r.int(7, 9), r.int(10, 12)], f = [r.int(2, 5), r.int(6, 9), r.int(2, 5), r.int(2, 5)]; return N(`A frequency table shows the values ${list(v)} with frequencies ${list(f)} respectively. What is the frequency of the mode?`, f[1], `The mode is ${v[1]}, with frequency ${f[1]}.`, {wr: [v[1], f[0], f[2], f[1] + 1]}); },
    r => { const o = withMode(r, 12, 20, 26); if (!o) return null; return N(`The ages of 12 children are ${list(o.d)}. How many children have the modal age?`, o.m, `${o.mode} is the mode and it appears ${o.m} times.`, {wr: [o.mode, o.m + 1, o.m - 1, Math.max(...o.d)]}); },
    r => { const a = r.int(2, 9), b = r.int(2, 9), c = r.int(2, 9); if (a === b || b === c || a === c) return null; return N(`The mode of ${a}, ${b}, ${a}, ${c}, ${b}, ${a}, ${c}, ${b}, ${a} is found. Find the mode.`, a, `${a} appears 4 times, ${b} appears 3 times and ${c} appears 2 times, so the mode is ${a}.`, {wr: [b, c, 4, a + 1]}); },
    r => { const o = withMode(r, 10, 5, 12); if (!o) return null; return N(`Find the mode of ${list(o.d)} and add 10 to it.`, o.mode + 10, `The mode is ${o.mode}. ${o.mode} + 10 = ${o.mode + 10}.`, {wr: [o.mode, o.m + 10, o.mode + 11, Math.max(...o.d) + 10]}); },
    r => mcq(r, 'A shopkeeper wants to know which shirt size to stock the most of. Which average should be used?', 'the mode', ['the mean', 'the range', 'the median'], 'The most common size is the mode, and it shows the size that sells most often.'),
    r => mcq(r, 'Which statement about the mode is true?', 'A data set can have more than one mode', ['A data set always has exactly one mode', 'The mode is the middle value', 'The mode is the sum divided by the number of values'], 'If two or more values have the same highest frequency, there is more than one mode.'),
    r => mcq(r, 'Which of the following data sets has no mode?', '2, 3, 4, 5, 6', ['2, 3, 3, 4, 5', '2, 2, 3, 3, 4', '1, 1, 1, 2, 3'], 'Every value appears once, so no value is more common than the others.')
  ], word: [
    r => { const o = withMode(r, 15, 5, 9); if (!o) return null; return N(`A shop recorded the shoe sizes of 15 customers: ${list(o.d)}. Which shoe size should the shop stock the most of (the modal size)?`, o.mode, `The size ${o.mode} occurs ${o.m} times, the most.`, {wr: [o.m, Math.max(...o.d), Math.min(...o.d), o.mode + 1]}); },
    r => { const o = withMode(r, 14, 1, 6); if (!o) return null; return N(`A survey asked 14 families how many cars they own: ${list(o.d)}. What is the mode?`, o.mode, `${o.mode} appears ${o.m} times, the most.`, {wr: [o.m, Math.max(...o.d), o.mode + 1, o.mode - 1 < 0 ? o.mode + 2 : o.mode - 1]}); },
    r => { const o = withMode(r, 12, 40, 49); if (!o) return null; return N(`A teacher recorded 12 test marks: ${list(o.d)}. How many students scored the modal mark?`, o.m, `${o.mode} is the mode and it appears ${o.m} times.`, {wr: [o.mode, o.m + 1, o.m - 1, Math.max(...o.d)]}); },
    r => { const v = [r.int(1, 3), r.int(4, 6), r.int(7, 9)], f = [r.int(2, 6), r.int(7, 11), r.int(2, 6)]; return N(`A table shows the number of siblings (${list(v)}) of students with frequencies ${list(f)}. What is the modal number of siblings?`, v[1], `The highest frequency is ${f[1]}, for ${v[1]} siblings. The mode is ${v[1]}.`, {wr: [f[1], v[0], v[2], v[1] + 1]}); },
    r => { const o = withMode(r, 11, 20, 30); if (!o) return null; return N(`The temperatures (in °C) at noon over 11 days were ${list(o.d)}. Find the modal temperature, in °C.`, o.mode, `${o.mode} appears ${o.m} times, the most.`, {wr: [o.m, Math.max(...o.d), o.mode + 1, o.mode - 1]}); }
  ]});

  /* ---- Probability ---- */
  gyms.push({id: 'G2.2.probability.1', plain: [
    r => { const R = r.int(2, 9), B = r.int(2, 18), T = R + B; if (![4, 5, 8, 10, 20, 25].includes(T)) return null; return N(`A bag has ${R} red balls and ${B} blue balls. One ball is picked at random. Find the probability that it is red. Give your answer as a decimal.`, R / T, `P(red) = ${R}/${T} = ${R / T}.`, {wr: [B / T, 1 / T, R / B, +(R / T + 0.1).toFixed(3)]}); },
    r => { const T = r.pick([20, 40, 50]), n = r.int(2, 9); const p = n / T; return N(`The probability that a bus is late is ${p}. Find the probability that the bus is not late. Give your answer as a decimal.`, 1 - p, `P(not late) = 1 − ${p} = ${+(1 - p).toFixed(3)}.`, {wr: [p, +(1 - p + 0.1).toFixed(3), 1, +(p * 2).toFixed(3)]}); },
    r => { const p = r.pick([0.1, 0.2, 0.25, 0.3, 0.4, 0.5]), n = r.pick([20, 40, 60, 80, 100, 200]); return N(`The probability that a seed grows is ${p}. Janet plants ${n} seeds. How many seeds are expected to grow?`, p * n, `Expected number = ${p} × ${n} = ${p * n}.`, {wr: [n - p * n, p * n + n * 0.1, n * p * 10, p * n * 2]}); },
    r => { const A = r.pick([0.1, 0.15, 0.2, 0.25, 0.3]), B = r.pick([0.2, 0.25, 0.3, 0.35]); return N(`In a lucky draw, the probability of winning a pen is ${A} and the probability of winning a notebook is ${B}. The two events cannot both happen. Find the probability of winning a pen or a notebook.`, +(A + B).toFixed(3), `P(pen or notebook) = ${A} + ${B} = ${+(A + B).toFixed(3)}.`, {wr: [+(A * B).toFixed(3), +(1 - A - B).toFixed(3), +(A + B + 0.1).toFixed(3), +Math.abs(A - B).toFixed(3)]}); },
    r => { const T = r.pick([20, 25, 40, 50]), k = r.int(2, 9); return N(`A class has ${T} students and ${k} of them wear glasses. A student is chosen at random. Find the probability that the student wears glasses. Give your answer as a decimal.`, k / T, `P = ${k}/${T} = ${k / T}.`, {wr: [(T - k) / T, k / (T + k), 1 / T, +(k / T + 0.1).toFixed(3)]}); },
    r => { const o = [r.int(2, 9), r.int(2, 9), r.int(2, 9)], T = o.reduce((a, b) => a + b, 0); if (![8, 10, 20, 25].includes(T)) return null; return N(`A spinner has three colours with ${o[0]}, ${o[1]} and ${o[2]} equal sectors respectively. Find the probability that the spinner lands on the colour with ${o[1]} sectors. Give your answer as a decimal.`, o[1] / T, `Total sectors = ${T}. P = ${o[1]}/${T} = ${o[1] / T}.`, {wr: [o[0] / T, o[2] / T, o[1] / (T - o[1]), 1 / T]}); },
    r => mcq(r, 'Which of the following could be a probability?', r.pick(['0.35', '0.8', '0', '1', '0.05']), r.shuffle(['1.2', '-0.3', '2', '1.05', '-1']).slice(0, 3), 'A probability is a number from 0 to 1, so negative numbers and numbers above 1 are not possible.'),
    r => mcq(r, 'What is the probability of an event that is certain to happen?', '1', ['0', '0.5', '100'], 'A certain event has probability 1; an impossible event has probability 0.'),
    r => mcq(r, 'What is the probability of getting a number greater than 6 when a fair six-sided die is rolled?', '0', ['1', '$\\dfrac{1}{6}$', '$\\dfrac{1}{2}$'], 'No face shows a number greater than 6, so the event is impossible and the probability is 0.')
  ], word: [
    r => { const T = r.pick([20, 25, 40, 50]), k = r.int(3, 9); return N(`A raffle has ${T} tickets numbered 1 to ${T}. Mei buys ${k} tickets. Find the probability that Mei wins the first prize. Give your answer as a decimal.`, k / T, `P = ${k}/${T} = ${k / T}.`, {wr: [(T - k) / T, 1 / T, k / (T - k), +(k / T + 0.1).toFixed(3)]}); },
    r => { const p = r.pick([0.2, 0.25, 0.3, 0.4]), d = r.pick([10, 20, 30, 40, 100]); return N(`The probability that it rains on a given day in April is ${p}. How many rainy days are expected in a ${d}-day period?`, p * d, `Expected number = ${p} × ${d} = ${p * d}.`, {wr: [d - p * d, p * d * 2, p * d * 10, p * d + d * 0.1]}); },
    r => { const T = r.pick([10, 20, 25, 40, 50]), r_ = r.int(2, 9); return N(`A box has ${T} sweets, ${r_} of them are strawberry. Ali takes one sweet without looking. Find the probability that it is NOT strawberry. Give your answer as a decimal.`, (T - r_) / T, `P(not strawberry) = ${(T - r_)}/${T} = ${(T - r_) / T}.`, {wr: [r_ / T, 1 / T, (T - r_) / r_, +((T - r_) / T - 0.1).toFixed(3)]}); },
    r => { const p = r.pick([0.05, 0.1, 0.2, 0.25]), n = r.pick([100, 200, 400, 500]); return N(`A factory finds that the probability that a toy is faulty is ${p}. Out of ${n} toys, how many are expected to be faulty?`, p * n, `Expected faulty toys = ${p} × ${n} = ${p * n}.`, {wr: [n - p * n, p * n * 2, p * n * 10, p * n + n * 0.1]}); },
    r => { const g = r.int(3, 9), b = r.int(2, 9), T = g + b; if (![5, 10, 20, 25, 8, 4].includes(T)) return null; return N(`A class has ${g} girls and ${b} boys. A student is picked at random. Find the probability that the student is a girl. Give your answer as a decimal.`, g / T, `P(girl) = ${g}/${T} = ${g / T}.`, {wr: [b / T, 1 / T, g / b, +(g / T + 0.1).toFixed(3)]}); }
  ]});

  return gyms;
};
